    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_wooosh_core_fn_method_coreeventlistener_on_event(
        it, FfiConverterTypeCoreEvent.lower(`event`),_status)
}
    }
    
    

    

    
    
