/**
 * @suppress
 */
public object FfiConverterTypeWoooshCore: FfiConverter<WoooshCore, Pointer> {

    override fun lower(value: WoooshCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): WoooshCore {
        return WoooshCore(value)
    }

    override fun read(buf: ByteBuffer): WoooshCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: WoooshCore) = 8UL

    override fun write(value: WoooshCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



