/**
 * The single source of UI truth (DESIGN.md §4). Discovery events are absent
 * by design: the native shells own mDNS discovery.
 */
sealed class CoreEvent {
    
    /**
     * A control channel is up. `peer_pubkey` is the peer's raw 32-byte
     * Ed25519 identity key, taken from the certificate it proved possession
     * of in the TLS handshake — pass it back to `connect_peer` /
     * `revoke_peer`. `device_type` is the peer's HELLO `dt` (None when it
     * sent an unknown value).
     */
    data class PeerConnected(
        val `peerId`: kotlin.String, 
        val `peerPubkey`: kotlin.ByteArray, 
        val `deviceName`: kotlin.String, 
        val `deviceType`: DeviceType?, 
        val `fingerprint`: kotlin.String, 
        val `trusted`: kotlin.Boolean) : CoreEvent() {
        companion object
    }
    
    data class PeerDisconnected(
        val `peerId`: kotlin.String) : CoreEvent() {
        companion object
    }
    
    data class PairingSas(
        val `peerId`: kotlin.String, 
        val `code`: kotlin.String) : CoreEvent() {
        companion object
    }
    
    /**
     * Emitted when pairing concludes (QR or SAS; success or failure/timeout).
     * On success `message` carries the peer's device name; on failure the
     * reason. `peer_pubkey` is the key that was (or would have been) pinned.
     */
    data class PairingResult(
        val `peerId`: kotlin.String, 
        val `peerPubkey`: kotlin.ByteArray, 
        val `fingerprint`: kotlin.String, 
        val `success`: kotlin.Boolean, 
        val `message`: kotlin.String?) : CoreEvent() {
        companion object
    }
    
    data class IncomingOffer(
        val `transferId`: kotlin.String, 
        val `peerId`: kotlin.String, 
        val `peerPubkey`: kotlin.ByteArray, 
        val `fromName`: kotlin.String, 
        val `deviceType`: DeviceType?, 
        val `trusted`: kotlin.Boolean, 
        val `fingerprint`: kotlin.String, 
        val `files`: List<OfferedFile>, 
        val `totalBytes`: kotlin.ULong) : CoreEvent() {
        companion object
    }
    
    /**
     * A transfer actually began (outgoing: DECISION accepted; incoming:
     * offer accepted). Carries the resolved manifest for progress UI.
     */
    data class TransferStarted(
        val `transferId`: kotlin.String, 
        val `peerId`: kotlin.String, 
        val `direction`: TransferDirection, 
        val `files`: List<OfferedFile>, 
        val `totalBytes`: kotlin.ULong) : CoreEvent() {
        companion object
    }
    
    data class Progress(
        val `transferId`: kotlin.String, 
        val `fileId`: kotlin.UInt, 
        val `bytesDone`: kotlin.ULong, 
        val `totalBytes`: kotlin.ULong, 
        val `rateBps`: kotlin.ULong, 
        val `etaSecs`: kotlin.ULong) : CoreEvent() {
        companion object
    }
    
    data class FileReady(
        val `transferId`: kotlin.String, 
        val `fileId`: kotlin.UInt, 
        val `stagedPath`: kotlin.String, 
        val `kind`: FileKind) : CoreEvent() {
        companion object
    }
    
    /**
     * `duration_ms` is the wall-clock time of *this attempt* (a resumed
     * transfer restarts the clock when `resume_transfer` is called), measured
     * from the moment bytes could start flowing — sender: DECISION received;
     * receiver: offer accepted — to the last DONE. Divide `bytes_transferred`
     * by it for the attempt's average rate.
     */
    data class TransferDone(
        val `transferId`: kotlin.String, 
        val `okFiles`: kotlin.UInt, 
        val `failedFiles`: kotlin.UInt, 
        val `bytesTransferred`: kotlin.ULong, 
        val `durationMs`: kotlin.ULong) : CoreEvent() {
        companion object
    }
    
    data class TransferError(
        val `transferId`: kotlin.String, 
        val `error`: kotlin.String, 
        val `resumable`: kotlin.Boolean) : CoreEvent() {
        companion object
    }
    
    /**
     * A pinned peer presented a different key (PROTOCOL.md §4.5) — surfaced
     * prominently, never silently re-pinned. `peer_id` is the DeviceID of the
     * *pinned* identity we expected; `presented_pubkey` is the key actually
     * offered, when the handshake got far enough to observe it.
     */
    data class KeyChanged(
        val `peerId`: kotlin.String, 
        val `expectedPubkey`: kotlin.ByteArray, 
        val `presentedPubkey`: kotlin.ByteArray?) : CoreEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreEvent : FfiConverterRustBuffer<CoreEvent>{
    override fun read(buf: ByteBuffer): CoreEvent {
        return when(buf.getInt()) {
            1 -> CoreEvent.PeerConnected(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalTypeDeviceType.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> CoreEvent.PeerDisconnected(
                FfiConverterString.read(buf),
                )
            3 -> CoreEvent.PairingSas(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> CoreEvent.PairingResult(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            5 -> CoreEvent.IncomingOffer(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalTypeDeviceType.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterString.read(buf),
                FfiConverterSequenceTypeOfferedFile.read(buf),
                FfiConverterULong.read(buf),
                )
            6 -> CoreEvent.TransferStarted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeTransferDirection.read(buf),
                FfiConverterSequenceTypeOfferedFile.read(buf),
                FfiConverterULong.read(buf),
                )
            7 -> CoreEvent.Progress(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            8 -> CoreEvent.FileReady(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeFileKind.read(buf),
                )
            9 -> CoreEvent.TransferDone(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            10 -> CoreEvent.TransferError(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            11 -> CoreEvent.KeyChanged(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterOptionalByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreEvent) = when(value) {
        is CoreEvent.PeerConnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterByteArray.allocationSize(value.`peerPubkey`)
                + FfiConverterString.allocationSize(value.`deviceName`)
                + FfiConverterOptionalTypeDeviceType.allocationSize(value.`deviceType`)
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterBoolean.allocationSize(value.`trusted`)
            )
        }
        is CoreEvent.PeerDisconnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
        }
        is CoreEvent.PairingSas -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterString.allocationSize(value.`code`)
            )
        }
        is CoreEvent.PairingResult -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterByteArray.allocationSize(value.`peerPubkey`)
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterBoolean.allocationSize(value.`success`)
                + FfiConverterOptionalString.allocationSize(value.`message`)
            )
        }
        is CoreEvent.IncomingOffer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterByteArray.allocationSize(value.`peerPubkey`)
                + FfiConverterString.allocationSize(value.`fromName`)
                + FfiConverterOptionalTypeDeviceType.allocationSize(value.`deviceType`)
                + FfiConverterBoolean.allocationSize(value.`trusted`)
                + FfiConverterString.allocationSize(value.`fingerprint`)
                + FfiConverterSequenceTypeOfferedFile.allocationSize(value.`files`)
                + FfiConverterULong.allocationSize(value.`totalBytes`)
            )
        }
        is CoreEvent.TransferStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterTypeTransferDirection.allocationSize(value.`direction`)
                + FfiConverterSequenceTypeOfferedFile.allocationSize(value.`files`)
                + FfiConverterULong.allocationSize(value.`totalBytes`)
            )
        }
        is CoreEvent.Progress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterUInt.allocationSize(value.`fileId`)
                + FfiConverterULong.allocationSize(value.`bytesDone`)
                + FfiConverterULong.allocationSize(value.`totalBytes`)
                + FfiConverterULong.allocationSize(value.`rateBps`)
                + FfiConverterULong.allocationSize(value.`etaSecs`)
            )
        }
        is CoreEvent.FileReady -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterUInt.allocationSize(value.`fileId`)
                + FfiConverterString.allocationSize(value.`stagedPath`)
                + FfiConverterTypeFileKind.allocationSize(value.`kind`)
            )
        }
        is CoreEvent.TransferDone -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterUInt.allocationSize(value.`okFiles`)
                + FfiConverterUInt.allocationSize(value.`failedFiles`)
                + FfiConverterULong.allocationSize(value.`bytesTransferred`)
                + FfiConverterULong.allocationSize(value.`durationMs`)
            )
        }
        is CoreEvent.TransferError -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`error`)
                + FfiConverterBoolean.allocationSize(value.`resumable`)
            )
        }
        is CoreEvent.KeyChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterByteArray.allocationSize(value.`expectedPubkey`)
                + FfiConverterOptionalByteArray.allocationSize(value.`presentedPubkey`)
            )
        }
    }

    override fun write(value: CoreEvent, buf: ByteBuffer) {
        when(value) {
            is CoreEvent.PeerConnected -> {
                buf.putInt(1)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterByteArray.write(value.`peerPubkey`, buf)
                FfiConverterString.write(value.`deviceName`, buf)
                FfiConverterOptionalTypeDeviceType.write(value.`deviceType`, buf)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterBoolean.write(value.`trusted`, buf)
                Unit
            }
            is CoreEvent.PeerDisconnected -> {
                buf.putInt(2)
                FfiConverterString.write(value.`peerId`, buf)
                Unit
            }
            is CoreEvent.PairingSas -> {
                buf.putInt(3)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
            is CoreEvent.PairingResult -> {
                buf.putInt(4)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterByteArray.write(value.`peerPubkey`, buf)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterBoolean.write(value.`success`, buf)
                FfiConverterOptionalString.write(value.`message`, buf)
                Unit
            }
            is CoreEvent.IncomingOffer -> {
                buf.putInt(5)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterByteArray.write(value.`peerPubkey`, buf)
                FfiConverterString.write(value.`fromName`, buf)
                FfiConverterOptionalTypeDeviceType.write(value.`deviceType`, buf)
                FfiConverterBoolean.write(value.`trusted`, buf)
                FfiConverterString.write(value.`fingerprint`, buf)
                FfiConverterSequenceTypeOfferedFile.write(value.`files`, buf)
                FfiConverterULong.write(value.`totalBytes`, buf)
                Unit
            }
            is CoreEvent.TransferStarted -> {
                buf.putInt(6)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterTypeTransferDirection.write(value.`direction`, buf)
                FfiConverterSequenceTypeOfferedFile.write(value.`files`, buf)
                FfiConverterULong.write(value.`totalBytes`, buf)
                Unit
            }
            is CoreEvent.Progress -> {
                buf.putInt(7)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterUInt.write(value.`fileId`, buf)
                FfiConverterULong.write(value.`bytesDone`, buf)
                FfiConverterULong.write(value.`totalBytes`, buf)
                FfiConverterULong.write(value.`rateBps`, buf)
                FfiConverterULong.write(value.`etaSecs`, buf)
                Unit
            }
            is CoreEvent.FileReady -> {
                buf.putInt(8)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterUInt.write(value.`fileId`, buf)
                FfiConverterString.write(value.`stagedPath`, buf)
                FfiConverterTypeFileKind.write(value.`kind`, buf)
                Unit
            }
            is CoreEvent.TransferDone -> {
                buf.putInt(9)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterUInt.write(value.`okFiles`, buf)
                FfiConverterUInt.write(value.`failedFiles`, buf)
                FfiConverterULong.write(value.`bytesTransferred`, buf)
                FfiConverterULong.write(value.`durationMs`, buf)
                Unit
            }
            is CoreEvent.TransferError -> {
                buf.putInt(10)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`error`, buf)
                FfiConverterBoolean.write(value.`resumable`, buf)
                Unit
            }
            is CoreEvent.KeyChanged -> {
                buf.putInt(11)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterByteArray.write(value.`expectedPubkey`, buf)
                FfiConverterOptionalByteArray.write(value.`presentedPubkey`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






