/**
 * Public error type crossing the FFI boundary.
 */
sealed class WoooshException(message: String): kotlin.Exception(message) {
        
        class NotStarted(message: String) : WoooshException(message)
        
        class AlreadyStarted(message: String) : WoooshException(message)
        
        class Io(message: String) : WoooshException(message)
        
        class Crypto(message: String) : WoooshException(message)
        
        class Connect(message: String) : WoooshException(message)
        
        class UnknownPeer(message: String) : WoooshException(message)
        
        class KeyChanged(message: String) : WoooshException(message)
        
        class QrKeyMismatch(message: String) : WoooshException(message)
        
    /**
     * The peer closed the connection with `PAIRING_REQUIRED` (§4.1): it is in
     * PairedOnly visibility and we are not a paired device. Shells should say
     * "this device only accepts transfers from paired devices" and offer to
     * pair, rather than reporting a generic failure.
     */
        class PairingRequired(message: String) : WoooshException(message)
        
    /**
     * The peer closed the connection with `VERSION_MISMATCH` (§4.1/§8): no
     * common protocol version.
     */
        class VersionMismatch(message: String) : WoooshException(message)
        
        class Pairing(message: String) : WoooshException(message)
        
        class InvalidQrPayload(message: String) : WoooshException(message)
        
        class Transfer(message: String) : WoooshException(message)
        
        class UnknownTransfer(message: String) : WoooshException(message)
        
        class Protocol(message: String) : WoooshException(message)
        
        class InvalidArgument(message: String) : WoooshException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WoooshException> {
        override fun lift(error_buf: RustBuffer.ByValue): WoooshException = FfiConverterTypeWoooshError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeWoooshError : FfiConverterRustBuffer<WoooshException> {
    override fun read(buf: ByteBuffer): WoooshException {
        
            return when(buf.getInt()) {
            1 -> WoooshException.NotStarted(FfiConverterString.read(buf))
            2 -> WoooshException.AlreadyStarted(FfiConverterString.read(buf))
            3 -> WoooshException.Io(FfiConverterString.read(buf))
            4 -> WoooshException.Crypto(FfiConverterString.read(buf))
            5 -> WoooshException.Connect(FfiConverterString.read(buf))
            6 -> WoooshException.UnknownPeer(FfiConverterString.read(buf))
            7 -> WoooshException.KeyChanged(FfiConverterString.read(buf))
            8 -> WoooshException.QrKeyMismatch(FfiConverterString.read(buf))
            9 -> WoooshException.PairingRequired(FfiConverterString.read(buf))
            10 -> WoooshException.VersionMismatch(FfiConverterString.read(buf))
            11 -> WoooshException.Pairing(FfiConverterString.read(buf))
            12 -> WoooshException.InvalidQrPayload(FfiConverterString.read(buf))
            13 -> WoooshException.Transfer(FfiConverterString.read(buf))
            14 -> WoooshException.UnknownTransfer(FfiConverterString.read(buf))
            15 -> WoooshException.Protocol(FfiConverterString.read(buf))
            16 -> WoooshException.InvalidArgument(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: WoooshException): ULong {
        return 4UL
    }

    override fun write(value: WoooshException, buf: ByteBuffer) {
        when(value) {
            is WoooshException.NotStarted -> {
                buf.putInt(1)
                Unit
            }
            is WoooshException.AlreadyStarted -> {
                buf.putInt(2)
                Unit
            }
            is WoooshException.Io -> {
                buf.putInt(3)
                Unit
            }
            is WoooshException.Crypto -> {
                buf.putInt(4)
                Unit
            }
            is WoooshException.Connect -> {
                buf.putInt(5)
                Unit
            }
            is WoooshException.UnknownPeer -> {
                buf.putInt(6)
                Unit
            }
            is WoooshException.KeyChanged -> {
                buf.putInt(7)
                Unit
            }
            is WoooshException.QrKeyMismatch -> {
                buf.putInt(8)
                Unit
            }
            is WoooshException.PairingRequired -> {
                buf.putInt(9)
                Unit
            }
            is WoooshException.VersionMismatch -> {
                buf.putInt(10)
                Unit
            }
            is WoooshException.Pairing -> {
                buf.putInt(11)
                Unit
            }
            is WoooshException.InvalidQrPayload -> {
                buf.putInt(12)
                Unit
            }
            is WoooshException.Transfer -> {
                buf.putInt(13)
                Unit
            }
            is WoooshException.UnknownTransfer -> {
                buf.putInt(14)
                Unit
            }
            is WoooshException.Protocol -> {
                buf.putInt(15)
                Unit
            }
            is WoooshException.InvalidArgument -> {
                buf.putInt(16)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




